  addEventListener("keyup", e => keys[e.key.toLowerCase()] = false);

  function pointerToGame(e) {
    const r = canvas.getBoundingClientRect();
    return {
      x: (e.clientX - r.left) / r.width * W,
      y: (e.clientY - r.top) / r.height * H
