    ctx.font = "14px system-ui";
    ctx.fillText("EXIT", exit.x + 5, exit.y + 37);

    sparks.forEach((s,i) => {
      if (s.got) return;
      const bob = Math.sin(t * 4 + i) * 3;
      ctx.fillStyle = "#9fffe1";
      ctx.beginPath(); ctx.arc(s.x, s.y + bob, 7, 0, Math.PI*2); ctx.fill();
