    ctx.beginPath();
    ctx.ellipse(-5,-9,13,7,-.5,0,Math.PI*2);
    ctx.ellipse(-5,9,13,7,.5,0,Math.PI*2);
    ctx.fill();
    ctx.fillStyle = "#f7dca0";
    ctx.beginPath(); ctx.ellipse(2,0,12,6,0,0,Math.PI*2); ctx.fill();
    ctx.fillStyle = "#fff8c9";
    ctx.beginPath(); ctx.arc(12,0,4,0,Math.PI*2); ctx.fill();
    ctx.restore();
  }

  function loop(now) {
    if (!running) return;
    const dt = Math.min(.033, (now - last) / 1000);
    last = now;
    update(dt);
    draw();
    requestAnimationFrame(loop);
  }

  draw();
})();
